function applyLanguage(root){
  const code=db.settings?.language||'en';
  const pack=LANG_PACKS[code]||LANG_PACKS.en;
  document.documentElement.lang=code;
  root.querySelectorAll('[data-i18n]').forEach(el=>{const k=el.getAttribute('data-i18n');if(pack[k])el.textContent=pack[k]});
  const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);
  const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);
  nodes.forEach(n=>{const raw=n.nodeValue.trim();if(pack[raw])n.nodeValue=n.nodeValue.replace(raw,pack[raw])});
  root.querySelectorAll('input[placeholder],textarea[placeholder]').forEach(el=>{const p=el.getAttribute('placeholder');if(pack[p])el.setAttribute('placeholder',pack[p])});
  root.querySelectorAll('button[aria-label],select[aria-label]').forEach(el=>{const a=el.getAttribute('aria-label');if(pack[a])el.setAttribute('aria-label',pack[a])});
}

