function fresh(){return {version:20,location:C.defaultLocation,users:seedUsers.map(x=>({...x})),session:null,products:seedProducts.map(x=>({...x,specs:{...x.specs},tags:[...x.tags]})),stores:seedStores.map(x=>({...x})),sellers:[],cart:[],wishlist:[],orders:[],services:serviceTypes.map((name,i)=>({id:'sv'+i,name,provider:['Vizag Home Services','QuickFix Local','CoolCare','Tech Local'][i%4],rating:(4.3+(i%6)/10).toFixed(1),price:199+(i%5)*100,available:i%3!==0})),bookings:[],wallet:{balance:0,ledger:[]},rfqs:[],quotes:[],ads:[],coupons:[{code:'JANA10',type:'percent',value:10,min:500,active:true}],rewards:0,notifications:[],tickets:[],reviews:[],cms:{heroTitle:"India's People's Marketplace",heroText:'Shop from brands, farmers, FPOs, homemade producers, Kirana stores, manufacturers, distributors and local businesses — plus services and digital utilities.'},settings:{demoIntegrations:false,language:'en'},locationData:{state:'',district:'',mandal:'',panchayat:'',village:'',pincode:'',lat:null,lng:null,source:'manual'}}}
let db=load();
function load(){try{const x=JSON.parse(localStorage.getItem(KEY));if(!x)return fresh();if(x.version===20)return x;const y=fresh();Object.assign(y,x);y.version=20;y.settings={...y.settings,...(x.settings||{})};y.locationData={...y.locationData,...(x.locationData||{})};return y}catch{return fresh()}}
function save(){localStorage.setItem(KEY,JSON.stringify(db))}
function user(){return db.session?db.users.find(x=>x.id===db.session):null}
function requireUser(role){const u=user();if(!u){authModal('login');return false}if(role && !([role,'super_admin','admin'].includes(u.role))){toast('This area requires '+role+' access');return false}return true}
function route(){return window.location.hash.replace(/^#/,'')||'home'}
function go(r){window.location.hash=r}
window.addEventListener('hashchange',()=>{try{render()}catch(err){fatal(err)}});
async function boot(){
  try{
    document.documentElement.lang=db.settings?.language||'en';
    render();
  }catch(err){fatal(err);return}
  try{await initSupabase(); if(supabaseAuthReady)render()}catch(err){console.warn('Optional Supabase initialization failed',err)}
}


function shell(content){const u=user();return `<header class="top"><div class="toprow"><a href="#home"><img class="logo" src="${A.header}" alt="JANA BAZAR" onerror="this.onerror=null;this.src='${esc(A.primary)}'"></a><button class="loc" onclick="JB.location()">📍 ${esc(db.location)}</button><select class="lang" onchange="JB.setLanguage(this.value)" aria-label="Language">${INDIA_LANGUAGES.map(([k,n])=>`<option value="${k}" ${db.settings.language===k?"selected":""}>${n}</option>`).join("")}</select><div class="search"><input id="globalSearch" placeholder="Search products, stores, services, B2B..." value="${esc(state.q||'')}"><button onclick="JB.search()">🔎</button><button onclick="JB.voice()">🎙️</button></div><nav class="nav"><button class="navbtn" onclick="JB.go('orders')">📦 Orders</button><button class="navbtn" onclick="JB.go('wishlist')">♡ Wishlist</button>${u?`<button class="navbtn" onclick="JB.go('account')">👤 ${esc(u.name.split(' ')[0])}</button>`:`<button class="primary" onclick="JB.auth('login')">Login</button>`}<button class="navbtn" onclick="JB.go('cart')">🛒 ${db.cart.reduce((a,x)=>a+x.qty,0)}</button></nav></div><div class="tabs">${categories.slice(0,15).map(c=>`<button class="tab" onclick="JB.category('${esc(c)}')">${esc(c)}</button>`).join('')}</div></header>${content}<footer class="footer"><div class="footergrid"><div>${img('dark','JANA BAZAR','') }<p>India's People's Marketplace</p><p class="muted">Products + Local Commerce + B2B + Services + Utilities</p></div><div><b>Marketplace</b><p>All Products</p><p>Local Commerce</p><p>B2B</p><p>Services</p></div><div><b>Business</b><p onclick="JB.go('seller')">Sell on JANA BAZAR</p><p onclick="JB.go('advertising')">Advertising Center</p><p onclick="JB.go('seller-dashboard')">Seller Dashboard</p></div><div><b>Platform</b><p onclick="JB.go('admin')">Admin Portal</p><p onclick="JB.go('support')">Help Center</p><p onclick="JB.go('policies')">Policies</p></div></div></footer><div class="bottom"><button onclick="JB.go('home')">🏠<br>Home</button><button onclick="JB.go('search')">🔎<br>Search</button><button onclick="JB.go('orders')">📦<br>Orders</button><button onclick="JB.go('cart')">🛒<br>Cart</button><button onclick="JB.go('account')">👤<br>Account</button></div>`}
const state={q:'',category:'All'};

function mount(){let el=document.getElementById('app');if(!el){el=document.createElement('div');el.id='app';(document.body||document.documentElement).appendChild(el);}return el;}
function render(){const root=mount();const r=route();let c='';if(r==='home')c=home();else if(r==='search')c=renderSearchPage();else if(r.startsWith('product/'))c=product(r.split('/')[1]);else if(r==='cart')c=cartPage();else if(r==='checkout')c=checkout();else if(r==='orders')c=orders();else if(r.startsWith('order/'))c=orderDetail(r.split('/')[1]);else if(r==='wishlist')c=wishlist();else if(r==='account')c=account();else if(r==='seller')c=sellerRegister();else if(r==='seller-dashboard')c=sellerDashboard();else if(r==='b2b')c=b2bPage();else if(r==='services')c=servicesPage();else if(r.startsWith('service/'))c=serviceDetail(r.split('/')[1]);else if(r==='utilities')c=utilitiesPage();else if(r==='wallet')c=walletPage();else if(r==='advertising')c=advertisingPage();else if(r==='support')c=supportPage();else if(r==='policies')c=policiesPage();else if(r==='admin')c=adminPage();else if(r.startsWith('admin/'))c=adminPage(r.split('/')[1]);else if(r==='service-provider')c=serviceProvider();else if(r==='delivery')c=deliveryPage();else c=home();root.innerHTML=shell(c);applyLanguage(root);return root;}

function home(){const products=db.products.slice(0,8);return `<main class="container"><section class="hero"><div><span class="eyebrow">ONE MARKETPLACE • MANY POSSIBILITIES</span><h1>${esc(db.cms.heroTitle)}</h1><p>${esc(db.cms.heroText)}</p><div class="actions"><button class="orange" onclick="JB.search()">Shop Now</button><button class="ghost" onclick="JB.go('services')">Explore Local</button><button class="ghost" onclick="JB.go('seller')">Start Selling</button></div></div>${img('dark','JANA BAZAR','heroLogo')}</section><section class="section"><div class="quickgrid"><div class="quick"><b>Marketplace</b><h2>Multi-Vendor</h2><p>Farmers → Brands → Retailers → Customers</p></div><div class="quick"><b>Local</b><h2>Hyperlocal</h2><p>Nearby stores, farmers and services</p></div><div class="quick"><b>B2B</b><h2>Bulk Buying</h2><p>RFQ, wholesale and procurement workflows</p></div><div class="quick"><b>Utilities</b><h2>24+ Modules</h2><p>Recharge, bills, FASTag, LPG and wallet</p></div></div></section><section class="section"><div class="sectionhead"><div><h2>Shop by ecosystem</h2><p class="muted">Discover every seller type in one marketplace.</p></div><button class="small" onclick="JB.search()">View all</button></div><div class="searchchips">${sellerTypes.map(x=>`<button class="chip" onclick="JB.sellerType('${esc(x)}')">${esc(x)}</button>`).join('')}</div></section><section class="section"><div class="sectionhead"><div><h2>Trending products</h2><p class="muted">Real catalog structure with variants, specifications, stock and seller information.</p></div><button class="small" onclick="JB.search()">All products</button></div><div class="products">${products.map(productCard).join('')}</div></section><section class="section"><div class="sectionhead"><h2>Nearby services</h2><button class="small" onclick="JB.go('services')">All services</button></div><div class="grid">${db.services.slice(0,8).map(serviceCard).join('')}</div></section><section class="section"><div class="sectionhead"><div><h2>Digital utilities</h2><p class="muted">Utility workflows are integration-ready and never fake a real transaction.</p></div><button class="small" onclick="JB.go('utilities')">Open utilities</button></div><div class="grid">${utilityTypes.map(utilityCard).join('')}</div></section><section class="section"><div class="card"><div class="sectionhead"><div><h2>JANA BAZAR Portals</h2><p class="muted">Dedicated experiences for every participant.</p></div></div><div class="logoGrid"><div class="card">${img('shop','Customer','portalLogo')}<h3>Customer</h3><button class="small primary" onclick="JB.go('account')">Open</button></div><div class="card">${img('seller','Seller','portalLogo')}<h3>Seller</h3><button class="small primary" onclick="JB.go('seller-dashboard')">Open</button></div><div class="card">${img('b2b','B2B','portalLogo')}<h3>B2B</h3><button class="small primary" onclick="JB.go('b2b')">Open</button></div><div class="card">${img('services','Services','portalLogo')}<h3>Services</h3><button class="small primary" onclick="JB.go('services')">Open</button></div><div class="card">${img('utilities','Utilities','portalLogo')}<h3>Utilities</h3><button class="small primary" onclick="JB.go('utilities')">Open</button></div><div class="card">${img('admin','Admin','portalLogo')}<h3>Admin</h3><button class="small primary" onclick="JB.go('admin')">Open</button></div></div></div></section></main>`}
function productCard(p){return `<article class="product"><div class="pimg"><img src="${esc(p.image)}" alt="${esc(p.name)}" onerror="this.onerror=null;this.src='${esc(A.primary)}'"></div><div class="pbody"><div class="rating">★ ${p.rating} (${p.reviews})</div><h3>${esc(p.name)}</h3><div class="muted">${esc(p.seller)} • ${esc(p.sellerType)}</div><div><span class="price">${money(p.price)}</span> <span class="strike">${money(p.mrp)}</span> <span class="badge">${p.discount}% off</span></div><div class="actions"><button class="small primary" onclick="JB.add('${p.id}')">Add to Cart</button><button class="small" onclick="JB.go('product/${p.id}')">View</button><button class="small" onclick="JB.wish('${p.id}')">♡</button></div></div></article>`}
function serviceCard(s){return `<div class="card service"><div style="font-size:28px">${serviceIcon(s.name)}</div><h3>${esc(s.name)}</h3><div class="muted">${esc(s.provider)} • ★ ${s.rating}</div><p>${s.available?'Available nearby':'Next available soon'}</p><button class="small primary" onclick="JB.go('service/${s.id}')">Book Service</button></div>`}
function utilityCard(u){const icons={'Recharge & Bills':'📱','FASTag':'🚗','LPG Services':'🔥','JANA Wallet':'💳'};return `<div class="card utility"><div style="font-size:28px">${icons[u]}</div><h3>${u}</h3><p class="muted">${u==='JANA Wallet'?'Wallet, cashback and transaction history.':u==='FASTag'?'Recharge and supported FASTag services.':u==='LPG Services'?'Supported LPG booking/service workflows.':'Mobile, DTH, electricity, broadband and supported billers.'}</p><button class="small primary" onclick="JB.go('${u==='JANA Wallet'?'wallet':'utilities'}')">Open</button></div>`}
function serviceIcon(n){return {'Electrician':'⚡','Plumber':'🔧','AC Service':'❄️','Computer Repair':'💻','Mobile Repair':'📱','Appliance Repair':'🔌','Carpenter':'🪚','Painter':'🎨','Cleaning':'🧹','Pest Control':'🛡️','RO Service':'💧','CCTV Service':'📹','Solar Service':'☀️','Home Maintenance':'🏠','Vehicle Service':'🚘','Emergency Help':'🚨'}[n]||'🛠️'}

function renderSearchPage(){const q=(state.q||'').toLowerCase();let list=db.products.filter(p=>state.category==='All'||p.category===state.category||p.sellerType===state.category);if(q)list=list.filter(p=>(p.name+' '+p.category+' '+p.seller+' '+p.sellerType+' '+p.tags.join(' ')).toLowerCase().includes(q));return `<main class="container"><div class="sectionhead"><div><h1>Search Marketplace</h1><p class="muted">Products, stores, services, sellers and B2B are searchable from one place.</p></div></div><div class="card"><div class="search"><input id="pageSearch" value="${esc(state.q)}" placeholder="Search products, stores, services, B2B"><button onclick="JB.submitSearchPage()">Search</button></div><div class="searchchips" style="margin-top:12px">${categories.map(c=>`<button class="chip" onclick="JB.category('${esc(c)}')">${esc(c)}</button>`).join('')}</div></div><section class="section"><div class="sectionhead"><h2>${list.length} products</h2><span class="muted">${state.category}</span></div><div class="products">${list.length?list.map(productCard).join(''):'<div class="empty">No products found. Try another search.</div>'}</div></section><section class="section"><div class="sectionhead"><h2>Nearby stores</h2></div><div class="grid">${db.stores.map(s=>`<div class="card"><h3>${esc(s.name)}</h3><span class="badge">${esc(s.type)}</span><p>📍 ${s.distance} km • ★ ${s.rating}</p><p>${s.open?'Open now':'Closed'} • ${s.delivery}</p><button class="small primary" onclick="JB.store('${s.id}')">View store</button></div>`).join('')}</div></section></main>`}
function product(id){const p=db.products.find(x=>x.id===id);if(!p)return `<main class="container"><div class="empty">Product not found</div></main>`;return `<main class="container"><div class="card"><div class="grid" style="grid-template-columns:1fr 1fr"><div class="pimg" style="height:420px"><img src="${esc(p.image)}" alt="${esc(p.name)}" onerror="this.onerror=null;this.src='${esc(A.primary)}'"></div><div><span class="badge">${esc(p.sellerType)}</span><h1>${esc(p.name)}</h1><p>★ ${p.rating} (${p.reviews} reviews) • ${esc(p.seller)}</p><div><span class="price">${money(p.price)}</span> <span class="strike">${money(p.mrp)}</span> <span class="badge">${p.discount}% OFF</span></div><p>${p.stock>0?`In stock — ${p.stock} available`:'Out of stock'}</p><div class="actions"><button class="primary" onclick="JB.add('${p.id}')">Add to Cart</button><button class="orange" onclick="JB.buy('${p.id}')">Buy Now</button><button class="small" onclick="JB.wish('${p.id}')">♡ Wishlist</button></div><div class="section"><h3>Specifications</h3>${Object.entries(p.specs||{}).map(([k,v])=>`<div style="display:flex;justify-content:space-between;padding:9px 0;border-bottom:1px solid var(--line)"><b>${esc(k)}</b><span>${esc(v)}</span></div>`).join('')}</div><div class="section"><h3>Seller & trust</h3><p>${esc(p.seller)} • ${esc(p.sellerType)} • Verified seller architecture</p><p class="muted">Returns, warranty, delivery and compliance are configured per category and seller policy.</p></div></div></div></div></main>`}
function cartPage(){if(!db.cart.length)return `<main class="container"><div class="card empty"><h2>Your cart is empty</h2><p>Discover products from farmers, Kirana, brands, manufacturers and local sellers.</p><button class="primary" onclick="JB.go('home')">Shop Now</button></div></main>`;const items=db.cart.map(i=>{const p=db.products.find(x=>x.id===i.id);return `<div class="card" style="display:flex;gap:12px;align-items:center">${p?`<img src="${esc(p.image)}" style="width:100px;height:90px;object-fit:cover;border-radius:10px">`:''}<div style="flex:1"><h3>${esc(p?.name||'Product')}</h3><p class="muted">${esc(p?.seller||'')}</p><b>${money((p?.price||0)*i.qty)}</b></div><div><button class="small" onclick="JB.qty('${i.id}',-1)">−</button> ${i.qty} <button class="small" onclick="JB.qty('${i.id}',1)">+</button></div><button class="danger" onclick="JB.remove('${i.id}')">Remove</button></div>`}).join('');const total=db.cart.reduce((s,i)=>s+(db.products.find(p=>p.id===i.id)?.price||0)*i.qty,0);return `<main class="container"><div class="sectionhead"><h1>Shopping Cart</h1><button class="small" onclick="JB.go('home')">Continue Shopping</button></div><div class="grid" style="grid-template-columns:2fr 1fr"><div>${items}</div><div class="card"><h2>Order Summary</h2><p>Items <span style="float:right">${money(total)}</span></p><p>Delivery <span style="float:right">${money(total>999?0:49)}</span></p><p>Platform coupon <span style="float:right">Eligible</span></p><hr><h2>Total <span style="float:right">${money(total+(total>999?0:49))}</span></h2><button class="primary" style="width:100%" onclick="JB.go('checkout')">Proceed to Checkout</button></div></div></main>`}
function checkout(){if(!requireUser())return '';const total=db.cart.reduce((s,i)=>s+(db.products.find(p=>p.id===i.id)?.price||0)*i.qty,0);return `<main class="container"><div class="sectionhead"><h1>Secure Checkout</h1><span class="badge">Integration-ready</span></div><div class="grid" style="grid-template-columns:1.5fr 1fr"><div class="card"><h3>Delivery Address</h3><div class="formgrid"><div class="field full"><input id="coAddress" placeholder="House / Street / Locality / City / PIN" value="Auto Nagar, Visakhapatnam"></div></div><h3>Delivery</h3><div class="actions"><button class="small primary">Standard Delivery</button><button class="small">Store Pickup</button><button class="small">Scheduled Slot</button></div><h3>Payment</h3><div class="grid" style="grid-template-columns:repeat(2,1fr)"><button class="card" onclick="JB.placeOrder('COD')">Cash on Delivery</button><button class="card" onclick="JB.placeOrder('ONLINE')">Online Payment (provider later)</button><button class="card" onclick="JB.placeOrder('WALLET')">JANA Wallet</button><button class="card" onclick="JB.placeOrder('UPI')">UPI (provider later)</button></div><p class="muted">Real payment, wallet debit and utility transactions are disabled until providers are configured. No fake success is generated.</p></div><div class="card"><h2>Payable</h2><h1>${money(total+(total>999?0:49))}</h1><p>${db.cart.length} line items • Multi-seller order architecture</p></div></div></main>`}
function orders(){if(!requireUser())return '';const mine=db.orders.filter(o=>o.userId===user().id);return `<main class="container"><div class="sectionhead"><h1>My Orders</h1><button class="small" onclick="JB.go('support')">Need Help?</button></div>${mine.length?mine.map(o=>`<div class="card" style="margin-bottom:12px"><div class="sectionhead"><div><b>Order ${esc(o.id)}</b><p class="muted">${new Date(o.createdAt).toLocaleString()}</p></div><span class="badge">${esc(o.status)}</span></div><p>${o.items.length} items • ${money(o.total)} • ${esc(o.payment)}</p><div class="actions"><button class="small primary" onclick="JB.go('order/${o.id}')">View Order</button><button class="small" onclick="JB.ticket('${o.id}')">Get Support</button></div></div>`).join(''):'<div class="card empty">No orders yet.</div>'}</main>`}
function orderDetail(id){if(!requireUser())return '';const o=db.orders.find(x=>x.id===id&&x.userId===user().id);if(!o)return `<main class="container"><div class="empty">Order not found.</div></main>`;return `<main class="container"><div class="card"><div class="sectionhead"><div><h1>Order ${esc(o.id)}</h1><p class="muted">Parent order with seller-wise fulfillment.</p></div><span class="badge">${esc(o.status)}</span></div><div class="section"><h3>Items</h3>${o.items.map(i=>`<p>${esc(i.name)} × ${i.qty} — ${money(i.price*i.qty)}</p>`).join('')}</div><div class="section"><h3>Lifecycle</h3><div class="actions">${['CREATED','PAID','CONFIRMED','PROCESSING','PACKED','SHIPPED','OUT_FOR_DELIVERY','DELIVERED'].map(x=>`<span class="chip">${x===o.status?'● ':''}${x}</span>`).join('')}</div></div><div class="section"><h3>Delivery</h3><p>Delivery OTP architecture enabled. Real OTP provider will be connected later.</p></div></div></main>`}
function wishlist(){if(!requireUser())return '';const list=db.products.filter(p=>db.wishlist.includes(p.id));return `<main class="container"><div class="sectionhead"><h1>Wishlist</h1></div><div class="products">${list.length?list.map(productCard).join(''):'<div class="empty">No saved products.</div>'}</div></main>`}
function account(){if(!requireUser())return '';const u=user();return `<main class="container"><div class="dashboard"><aside class="card side">${img('shop','Customer','portalLogo')}<h3>${esc(u.name)}</h3><span class="badge">Customer</span><button class="active" onclick="JB.go('account')">Profile</button><button onclick="JB.go('orders')">Orders</button><button onclick="JB.go('wishlist')">Wishlist</button><button onclick="JB.go('wallet')">Wallet</button><button onclick="JB.go('support')">Support</button><button onclick="JB.logout()">Logout</button></aside><section><h1>Customer Account</h1><div class="grid"><div class="card"><h3>Profile</h3><p>${esc(u.email)}</p><p>${esc(u.mobile||'')}</p><button class="small" onclick="JB.auth('profile')">Edit / Verify</button></div><div class="card"><h3>Security</h3><p>OTP, password recovery, device management and sensitive-action verification are integration-ready.</p><button class="small" onclick="JB.auth('security')">Security Center</button></div><div class="card"><h3>Rewards</h3><p>${db.rewards} JANA Rewards</p></div><div class="card"><h3>Addresses</h3><p>Default: Auto Nagar, Visakhapatnam</p></div></div></section></div></main>`}

function sellerRegister(){return `<main class="container"><div class="card"><div class="brandline">${img('seller','Seller','portalLogo')}<div><h1>Sell on JANA BAZAR</h1><p class="muted">Farmer, FPO, Homemade, Kirana, Manufacturer, Brand, Distributor, Dealer, Wholesaler, Retailer or Service Provider.</p></div></div><form onsubmit="JB.sellerSubmit(event)"><div class="formgrid"><div class="field"><label>Business Name</label><input id="sbusiness" required></div><div class="field"><label>Seller Type</label><select id="stype" required>${sellerTypes.map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>Mobile</label><input id="smobile" required inputmode="tel"></div><div class="field"><label>Email</label><input id="semail" type="email" required></div><div class="field"><label>PAN / Business ID</label><input id="span"></div><div class="field"><label>GSTIN (if applicable)</label><input id="sgst"></div><div class="field full"><label>Business Address</label><textarea id="saddress"></textarea></div></div><div class="alert" style="margin:14px 0">OTP/KYC, bank verification and admin approval are required before production selling. Provider integrations will be connected later.</div><button class="primary">Submit for KYC Approval</button></form></div></main>`}
function sellerDashboard(){if(!requireUser('seller'))return '';return `<main class="container"><div class="dashboard"><aside class="card side">${img('seller','Seller','portalLogo')}<h3>Seller Control Center</h3>${['Overview','Products','Inventory','Orders','Store','Advertising','Finance','Analytics','KYC','Staff','Support'].map(x=>`<button onclick="JB.sellerTab('${x}')">${x}</button>`).join('')}</aside><section id="sellerPanel">${sellerTab('Overview')}</section></div></main>`}
